extension_probe.source:
module probe;
  typedef bit signed [1:0] s2_t;
  localparam s2_t PA [0:0] = '{2'b11};
  localparam bit P_ARRAY = 3'b111 inside {PA};
  localparam bit P_LIST = 3'b111 inside {PA[0]};
  s2_t sa [0:0], sa2 [0:1];
  logic [2:0] a;
  initial begin
    sa[0] = 2'b11;
    a = 3'b111;
    $display("E1 a=111 array=%b listed=%b", a inside {sa}, a inside {sa[0]});
    a = 3'b011;
    $display("E2 a=011 array=%b listed=%b", a inside {sa}, a inside {sa[0]});
    sa2[0] = 2'b01;
    sa2[1] = 2'b11;
    a = 3'b111;
    $display("E3 a=111 two array=%b listed=%b", a inside {sa2}, a inside {sa2[0], sa2[1]});
    $display("E4 constant array=%b listed=%b", P_ARRAY, P_LIST);
    $finish;
  end
endmodule
